// Orchestrator
[FunctionName("OnboardingOrchestrator")]
public async Task Run(
    [DurableTaskTrigger] IDurableOrchestrationContext ctx)
{
    var userId = ctx.GetInput<string>();
    await ctx.CallActivityAsync("SendWelcomeEmail", userId);
    await ctx.CallActivityAsync("ProvisionResources", userId);
    await ctx.CallActivityAsync("NotifyTeam", userId);
}

// Activity
[FunctionName("SendWelcomeEmail")]
public async Task SendWelcomeEmail([ActivityTrigger] string userId)
{
    await _emailService.SendAsync(userId, "Welcome!");
}
